private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (i < 4 && bb.hasRemaining()) {
        int byteValue = bb.get();
        if (byteValue < 0) {
            throw new InvalidInputException("Invalid UTF-8 byte value");
        }
        int index = (byteValue & 0x0F) + i * 0x80;
        if (byteValue >= 0x80 && byteValue <= 0xBF) {
            i += 1;
        } else if (byteValue >= 0xC0 && byteValue <= 0xDF) {
            i += 2;
        } else if (byteValue >= 0xE0 && byteValue <= 0xEF) {
            i += 3;
        } else {
            throw new InvalidInputException("Invalid UTF-8 byte value");
        }
        sb.append((char) index);
    }
    return i;
}
