public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    if (actualTypeArguments.length != targetType.getGenericSuperclass().getTypeParameters().length) {
        return null;
    }
    Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
    for (int i = 0; i < actualTypeArguments.length; ++i) {
        Type actualType = actualTypeArguments[i];
        Class<?> resolvedArgument = resolveTypeVariable(actualType, targetType.getGenericSuperclass());
        if (resolvedArgument == null) {
            return null;
        }
        resolvedArguments[i] = resolvedArgument;
    }
    return resolvedArguments;
}

private static Class<?> resolveTypeVariable(Type type, Type genericSuperclass) {
    if (type instanceof WildcardType) {
        WildcardType wildcardType = (WildcardType) type;
        Type lowerBound = wildcardType.getLowerBound();
        if (lowerBound instanceof WildcardType) {
            return resolveTypeVariable(lowerBound, genericSuperclass);
        }
        if (lowerBound instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) lowerBound;
            if (typeVariable.getGenericDeclaration() == genericSuperclass) {
                return typeVariable.getBounds()[0];
            }
        }
    } else if (type instanceof TypeVariable) {
        TypeVariable<?> typeVariable = (TypeVariable<?>) type;
        if (typeVariable.getGenericDeclaration() == genericSuperclass) {
            return Object.class;
        }
    }
    Type enclosingType = TypeUtils.getDeclaringClass(genericSuperclass, type);
    if (enclosingType != null) {
        return resolveTypeVariable(enclosingType, genericSuperclass);
    }
    return null;
}
