public static void createConfigurationDirectory(){
    // Obtain the user's home directory
    String userHome = System.getProperty("user.home");

    // Determine the configuration directory path
    String configurationDirPath = null;
    String operatingSystem = System.getProperty("os.name").toLowerCase();

    // Different operating systems require different paths
    if (operatingSystem.contains("windows")) {
        // On Windows, the "lf5" directory is created in the Documents and Settings directory
        configurationDirPath = "C:\\Documents and Settings\\" + userHome + "\\lf5";
    } else {
        // On other platforms, the configuration directory is created where the user home variable points
        configurationDirPath = userHome;
    }

    // Create the configuration directory
    File directory = new File(configurationDirPath);
    if (!directory.exists()) {
        directory.mkdirs();
    }
    System.out.println("Configuration directory created at " + configurationDirPath);
}
