import java.util.LinkedList;
import java.util.List;

public abstract class Spliterator {
    private final long FETCH_DATA_DURATION = 1000L; // Placeholder for actual duration

    protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new LinkedList<>();
        long startTime;
        long endTime;

        if (start < 0) {
            startTime = 0;
        } else {
            startTime = Math.max(start - FETCH_DATA_DURATION, 0);
        }

        if (end >= FETCH_DATA_DURATION) {
            endTime = end;
        } else {
            endTime = Math.min(end + FETCH_DATA_DURATION, FETCH_DATA_DURATION);
        }

        if (startTime < endTime) {
            timeRanges.add(new TimeRange(startTime, endTime));
        }

        return timeRanges;
    }
}
