public static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = timeBucket / (1000 * 24 * 60 * 60 * 365);
    long month = (timeBucket % (1000 * 24 * 60 * 60 * 365)) / (1000 * 24 * 60 * 60);
    long day = timeBucket % (1000 * 24 * 60 * 60);
    int dayOfMonth = day / (24 * 60 * 60);

    if(dayOfMonth < dayStep){
        long newDayOfMonth = dayOfMonth % dayStep;
        return year * (1000 * 24 * 60 * 60 * 365) + month * (1000 * 24 * 60 * 60) +
               dayStep * (1000 * 24 * 60 * 60 * (newDayOfMonth + 1) - 1);
    }
    return year * (1000 * 24 * 60 * 60 * 365) + month * (1000 * 24 * 60 * 60) + 
           dayStep * (1000 * 24 * 60 * 60 * dayOfMonth);
}
