    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }

    int length = str.length();
    int pos = 0;
    while (pos < length) {
        int codePoint = str.codePointAt(pos);
        if (isHighSurrogate(codePoint)) {
            if (pos + 1 >= length) {
                throw new IllegalArgumentException("Invalid surrogate pair");
            }
            int high = codePoint;
            int low = str.codePointAt(pos + 1);
            if (!isLowSurrogate(low)) {
                throw new IllegalArgumentException("Invalid surrogate pair");
            }
            compiledUtf8[totalLength++] = (byte) ((high - FIRST_HIGH_SURROGATE) << 10);
            compiledUtf8[totalLength++] = (byte) ((low - FIRST_LOW_SURROGATE) & 0xFF);
            pos += 2;
        } else {
            compiledUtf8[totalLength++] = (byte) (codePoint & 0xFF);
            pos++;
        }
    }
}
