public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }

    double width = box.getWidth();
    double halfWidth = width / 2;

    // Create two new boxes by offsetting the center point
    Box2D upperBox = new Box2D(box.getCenterX(), box.getCenterY() + halfWidth, box.getX(), box.getY() + box.getHeight());
    Box2D lowerBox = new Box2D(box.getCenterX(), box.getCenterY() - halfWidth, box.getX(), box.getY());

    return Pair.with(upperBox, lowerBox);
}
