public static int nextPrime(int desiredCapacity){
    // Handle the edge case where desiredCapacity is 0 or negative
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("Desired capacity must be a positive integer");
    }

    // If desiredCapacity is less than or equal to 31, return the smallest number that is a prime
    if (desiredCapacity <= 31) {
        return 31;
    }

    // Handle the special case where desiredCapacity is a power of 2 minus 1
    if ((desiredCapacity & (desiredCapacity - 1)) == 0) {
        return desiredCapacity;
    }

    // Find the next prime number less than or equal to desiredCapacity
    int candidate = (int) (desiredCapacity * 1.0519615242746633);
    while (!isPrime(candidate)) {
        candidate++;
    }

    return candidate;
}
