import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class MinLowerBoundFinder {
    private List<Integer> computeUpperBounds(List<K> keys) {
        Collections.sort(keys, Collections.reverseOrder());
        Map<Integer, Integer> lowerBoundMap = new HashMap<>();
        int lowerBound = Integer.MIN_VALUE;
        for (int key : keys) {
            lowerBoundMap.put(key, lowerBound);
            lowerBound = Math.max(lowerBound, key - 1);
        }
        return Collections.singletonList(lowerBoundMap.values().iterator().next());
    }
}
